package ais.common.newui.finance;import java.util.List;import javax.servlet.http.HttpServletRequest;import javax.servlet.http.HttpServletResponse;import org.json.JSONArray;import org.json.JSONObject;import ais.action.master.helper.util.TunggakanMahasiswaBaruProcessor;import ais.action.master.helper.util.TunggakanMahasiswaDaftarUlangProcessor;import ais.common.Common;import ais.common.newui.NewUiRouteGuard;import ais.common.newui.finance.NewUiStudentArrearsService.Detail;import ais.common.newui.finance.NewUiStudentArrearsService.Details;import ais.common.newui.finance.NewUiStudentArrearsService.Filter;import ais.common.newui.finance.NewUiStudentArrearsService.Option;import ais.common.newui.finance.NewUiStudentArrearsService.Options;import ais.common.newui.finance.NewUiStudentArrearsService.Row;import ais.common.newui.finance.NewUiStudentArrearsService.Snapshot;
/** Endpoint native tunggakan mahasiswa, termasuk processor existing tanpa UI ZK. */
public final class NewUiStudentArrearsController{private NewUiStudentArrearsController(){}public static void handle(HttpServletRequest q,HttpServletResponse r)throws Exception{r.setContentType("application/json; charset=UTF-8");r.setHeader("Cache-Control","no-store");JSONObject j=new JSONObject();try{String a=text(q.getParameter("action"),"list"),p=("settle".equals(a)||"reprocess".equals(a))?"update":"delete".equals(a)?"delete":"list";if(!NewUiRouteGuard.isActionAuthorized(q,"root","tunggakan_mahasiswa",p)){r.setStatus(403);fail(j,"ACTION_FORBIDDEN","Hak akses tidak tersedia.");write(r,j);return;}NewUiStudentArrearsService s=new NewUiStudentArrearsService();if("list".equals(a))encode(j,s.load(filter(q)));else if("options".equals(a))options(j,s.options());else if("details".equals(a))details(j,s.details(requiredId(q.getParameter("id"))));else if("job".equals(a))job(j);else{csrf(q);if("settle".equals(a))s.settle(requiredId(q.getParameter("id")),bool(q.getParameter("value")),Common.getCurrentUser(q));else if("delete".equals(a))s.delete(requiredId(q.getParameter("id")));else if("reprocess".equals(a)){start(text(q.getParameter("kind"),"existing"),text(q.getParameter("academicYear"),""),text(q.getParameter("semester"),"Ganjil"),bool(q.getParameter("reloadDetails")));job(j);}else throw new IllegalArgumentException("Aksi tidak dikenal.");}j.put("ok",true);}catch(SecurityException e){r.setStatus(403);fail(j,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException e){r.setStatus(422);fail(j,"VALIDATION_FAILED",e.getMessage());}catch(Exception e){r.setStatus(500);fail(j,"INTERNAL_ERROR","Gagal memproses tunggakan mahasiswa.");try{ais.common.ErrorAuditUtil.record(e,"NewUiStudentArrearsController");}catch(Exception ignored){}}write(r,j);}
 private static Filter filter(HttpServletRequest q){Filter f=new Filter();f.query=q.getParameter("q");f.academicYear=q.getParameter("academicYear");f.program=q.getParameter("program");f.citizenship=q.getParameter("citizenship");f.year=integerObject(q.getParameter("year"));f.semester=integerObject(q.getParameter("semester"));f.facultyId=id(q.getParameter("facultyId"));f.studyProgramId=id(q.getParameter("studyProgramId"));f.studentStatusId=id(q.getParameter("studentStatusId"));f.initialStatusId=id(q.getParameter("initialStatusId"));f.concentrationId=id(q.getParameter("concentrationId"));f.levelId=id(q.getParameter("levelId"));f.advisorId=id(q.getParameter("advisorId"));f.advisorMissing=bool(q.getParameter("advisorMissing"));f.statusAcademicYear=Common.getCurrentTahunAkademik();f.statusSemesterOdd=Common.isNowSemensterGanjil();f.unpaidOnly=bool(q.getParameter("unpaidOnly"));f.settledOnly=bool(q.getParameter("settledOnly"));f.page=Math.max(0,integer(q.getParameter("page"),0));f.size=Math.min(100,Math.max(10,integer(q.getParameter("size"),20)));return f;}
 private static synchronized void start(String kind,String ta,String semester,boolean detail){if(running(kind))throw new IllegalArgumentException("Processor masih berjalan.");Runnable task;if("new".equals(kind))task=new TunggakanMahasiswaBaruProcessor(false,Boolean.valueOf(detail),true,ta);else task=new TunggakanMahasiswaDaftarUlangProcessor(false,Boolean.valueOf(detail),true,ta,semester);Thread thread=new Thread(task,"new-ui-arrears-"+kind);thread.setDaemon(true);thread.start();}
 private static boolean running(String kind){int all="new".equals(kind)?TunggakanMahasiswaBaruProcessor.mahasiswas.size():TunggakanMahasiswaDaftarUlangProcessor.mahasiswas.size(),done="new".equals(kind)?TunggakanMahasiswaBaruProcessor.mahasiswasSudah.size():TunggakanMahasiswaDaftarUlangProcessor.mahasiswasSudah.size();return all>0&&done<all;}
 private static void job(JSONObject j)throws Exception{int oldAll=TunggakanMahasiswaDaftarUlangProcessor.mahasiswas.size(),oldDone=TunggakanMahasiswaDaftarUlangProcessor.mahasiswasSudah.size(),newAll=TunggakanMahasiswaBaruProcessor.mahasiswas.size(),newDone=TunggakanMahasiswaBaruProcessor.mahasiswasSudah.size();j.put("existing",new JSONObject().put("total",oldAll).put("done",oldDone).put("running",oldAll>0&&oldDone<oldAll)).put("newStudents",new JSONObject().put("total",newAll).put("done",newDone).put("running",newAll>0&&newDone<newAll));}
 private static void encode(JSONObject j,Snapshot s)throws Exception{JSONArray a=new JSONArray();for(Row x:s.rows)a.put(new JSONObject().put("id",x.id).put("studentId",x.studentId).put("academicYear",x.academicYear).put("semester",x.semester).put("nim",x.nim).put("name",x.name).put("cohort",x.cohort).put("citizenship",x.citizenship).put("startSemester",x.startSemester).put("faculty",x.faculty).put("studyProgram",x.studyProgram).put("status",x.status).put("program",x.program).put("debt",x.debt).put("remaining",x.remaining).put("paid",x.paid).put("paidPercent",x.paidPercent).put("settled",x.settled).put("hasPayment",x.hasPayment).put("note",x.note));j.put("rows",a).put("total",s.total).put("records",s.records).put("debt",s.debt);}private static void details(JSONObject j,Details d)throws Exception{j.put("charges",detail(d.charges)).put("payments",detail(d.payments));}private static JSONArray detail(List<Detail>v)throws Exception{JSONArray a=new JSONArray();for(Detail x:v)a.put(new JSONObject().put("name",x.name).put("amount",x.amount));return a;}
 private static void options(JSONObject j,Options o)throws Exception{j.put("statuses",options(o.statuses)).put("initialStatuses",options(o.initialStatuses)).put("faculties",options(o.faculties)).put("studyPrograms",options(o.studyPrograms)).put("concentrations",options(o.concentrations)).put("levels",options(o.levels));}private static JSONArray options(List<Option>v)throws Exception{JSONArray a=new JSONArray();for(Option x:v)a.put(new JSONObject().put("id",x.id).put("label",x.label).put("parentId",x.parentId));return a;}
 private static void csrf(HttpServletRequest q){if(!"POST".equalsIgnoreCase(q.getMethod()))throw new SecurityException("Metode HTTP tidak valid.");Object e=q.getSession().getAttribute("newUiCsrfToken");String v=q.getHeader("X-CSRF-Token");if(e==null||v==null||!String.valueOf(e).equals(v))throw new SecurityException("Token CSRF tidak valid.");}private static Long requiredId(String v){Long x=id(v);if(x==null)throw new IllegalArgumentException("ID wajib diisi.");return x;}private static Long id(String v){if(clean(v)==null)return null;try{return Long.valueOf(v);}catch(Exception e){throw new IllegalArgumentException("ID tidak valid.");}}private static Integer integerObject(String v){return clean(v)==null?null:Integer.valueOf(integer(v,0));}private static int integer(String v,int d){try{return Integer.parseInt(v);}catch(Exception e){return d;}}private static boolean bool(String v){return"true".equalsIgnoreCase(v);}private static String clean(String v){return v==null||v.trim().length()==0?null:v.trim();}private static String text(String v,String d){return clean(v)==null?d:v.trim();}private static void fail(JSONObject j,String c,String m)throws Exception{j.put("ok",false).put("code",c).put("message",m);}private static void write(HttpServletResponse r,JSONObject j)throws Exception{r.getWriter().write(j.toString());}}
